type Store struct{ m map[string]any }

func (s *Store) Set(id string, v any) { s.m[id] = v }

func (s *Store) Get(id string) (any, error) {
	v, ok := s.m[id]
	if !ok {
		return nil, fmt.Errorf("missing %s", id)
	}
	return v, nil
}

type Customer struct{ Name string }

func main() {
	s := &Store{m: map[string]any{}}
	s.Set("c1", 42)
	v, _ := s.Get("c1")
	c := v.(Customer)
	fmt.Println(c.Name)
}

package store

type CustomerStorage interface {
	Get(id string) (Customer, error)
	ListAll() ([]Customer, error)
	Create(c Customer) error
	Update(c Customer) error
	Delete(id string) error
	Close() error
}

func New() CustomerStorage { return &Store{} }
